+        if (Character.isJavaIdentifierStart(first) == false) {
+            return false;
+        }
+
+        int i = Character.charCount(first);
+        while (i < str.length()) {
+            int cp = Character.codePointAt(str, i);
+            if (Character.isJavaIdentifierPart(cp) == false) {
+                return false;
+            }
