+        jarEntries.put(moduleInfoPath, classToBytes.get("module-info"));
+        jarEntries.put(prefix + "/p/FooIntSupplier.class", classToBytes.get("p.FooIntSupplier"));
+        jarEntries.put(prefix + "/q/Bar.class", classToBytes.get("q.Bar"));
