+        Integer successful = (Integer) nodesResultMap.get("successful");
+        Integer failed = (Integer) nodesResultMap.get("failed");
+        assertThat(total, greaterThan(0));
+        assertThat(successful, equalTo(total));
+        assertThat(failed, equalTo(0));
+        return successful;
+    }
+
