+        """
+    }
+
+    def "ignores dependencies with org.elasticsearch"() {
+        given:
+        def group = "org.elasticsearch.gradle"
+        generateDummyJars(group)
+        file('signature-file.txt') << "@defaultMessage non-public internal runtime class"
+
+        buildFile << """
+            dependencies {
