+    @Override
+    public void run() {
+        try {
+            String line;
+            while ((line = reader.readLine()) != null) {
+                if (line.isEmpty() == false && line.charAt(0) == USER_EXCEPTION_MARKER) {
+                    userExceptionMsg = line.substring(1);
